"""PHB PDF 57–64 read; table 58 and domain pages 60–64 visually checked."""
from curated import record, source
from spell_extract import slug

CLASS='phb2014:class:cleric'
DOMAINS={
 'knowledge':(60,['Command','Identify','Augury','Suggestion','Nondetection','Speak with Dead','Arcane Eye','Confusion','Legend Lore','Scrying']),
 'life':(61,['Bless','Cure Wounds','Lesser Restoration','Spiritual Weapon','Beacon of Hope','Revivify','Death Ward','Guardian of Faith','Mass Cure Wounds','Raise Dead']),
 'light':(62,['Burning Hands','Faerie Fire','Flaming Sphere','Scorching Ray','Daylight','Fireball','Guardian of Faith','Wall of Fire','Flame Strike','Scrying']),
 'nature':(62,['Animal Friendship','Speak with Animals','Barkskin','Spike Growth','Plant Growth','Wind Wall','Dominate Beast','Grasping Vine','Insect Plague','Tree Stride']),
 'tempest':(63,['Fog Cloud','Thunderwave','Gust of Wind','Shatter','Call Lightning','Sleet Storm','Control Water','Ice Storm','Destructive Wave','Insect Plague']),
 'trickery':(64,['Charm Person','Disguise Self','Mirror Image','Pass Without Trace','Blink','Dispel Magic','Dimension Door','Polymorph','Dominate Person','Modify Memory']),
 'war':(64,['Divine Favor','Shield of Faith','Magic Weapon','Spiritual Weapon',"Crusader's Mantle",'Spirit Guardians','Freedom of Movement','Stoneskin','Flame Strike','Hold Monster'])
}


def apply_cleric_reviews(entities):
    by_id={e['id']:e for e in entities};added=[]
    channel={'pool':'cleric-channel-divinity','cost':1}
    daily={'maximumUses':'max(1,wisdomModifier)','recovery':['long-rest']}
    rows=[
      ('knowledge',1,'Blessings of Knowledge','Benedizioni della Conoscenza',60,{'languagesChoose':2,'skillsChoose':2,'skillPool':['arcana','history','nature','religion'],'chosenSkillsProficient':True,'chosenSkillChecksProficiencyMultiplier':2},'Impari due lingue e due abilità fra Arcano, Storia, Natura e Religione; competenza raddoppiata nelle prove delle abilità scelte.'),
      ('knowledge',2,'Knowledge of the Ages','Conoscenza delle Ere',60,{'activation':'action','resourceCost':channel,'chooseOne':'skill-or-tool','proficiencyMinutes':10},'Un uso di Incanalare Divinità e un’azione danno competenza in un’abilità o strumento scelto per dieci minuti.'),
      ('knowledge',6,'Read Thoughts','Leggere Pensieri',[60,61],{'activation':'action','resourceCost':channel,'target':'visible-creature-within-60-ft','save':'wisdom','saveDC':'cleric-spell-save-DC','success':'cannot-target-again-until-own-long-rest','failure':{'read':'surface-thoughts','durationMinutes':1,'requiresTargetWithinFt':60},'duringEffect':{'activation':'action','endsThoughtReading':True,'castSpellId':'phb2014:spell:suggestion','spellSlotRequired':False,'targetAutomaticallyFailsSave':True}},'Leggi i pensieri superficiali di una creatura visibile entro sessanta piedi che fallisce il TS Saggezza, per un minuto entro gittata. Un’azione può terminare la lettura e lanciare Suggestione senza slot, con fallimento automatico del TS; successo iniziale impedisce ulteriori tentativi fino al riposo lungo.'),
      ('knowledge',17,'Visions of the Past','Visioni del Passato',61,{'minimumMeditationMinutes':1,'maximumMeditationMinutes':'wisdomScore','concentration':'as-on-spell','resource':{'uses':1,'recovery':['short-rest','long-rest']},'objectReading':{'requires':'hold-object','afterFirstMinute':['previous-owner-acquired-and-lost-object','most-recent-significant-event-involving-owner-and-object'],'earlierOwnerMaximumDaysAgo':'wisdomScore','additionalMinutesPerOwner':1},'areaReading':{'maximumCubeSideFt':50,'maximumDaysAgo':'wisdomScore','significantEventsPerMinute':1,'order':'most-recent-first'}},'Meditazione concentrata di almeno un minuto e fino al punteggio di Saggezza. Leggi vicende dei precedenti proprietari di un oggetto tenuto oppure eventi significativi nell’area di cinquanta piedi, fino a tanti giorni quanto Saggezza, dal più recente. Recupero con riposo breve o lungo.'),
      ('life',1,'Bonus Proficiency','Competenza Aggiuntiva',61,{'armorProficiency':'heavy'},'Competenza nelle armature pesanti.'),
      ('life',1,'Disciple of Life','Discepolo della Vita',61,{'trigger':'use-spell-of-level-one-or-higher-to-restore-creature-hit-points','additionalHealing':'2+spellLevel'},'Ogni uso di una magia dal primo livello che cura una creatura aggiunge due PF più il livello della magia.'),
      ('life',2,'Preserve Life','Preservare Vita',61,{'activation':'action','requires':'present-holy-symbol','resourceCost':channel,'healingPool':'5*clericLevel','targets':'any-chosen-creatures-within-30-ft','distributeChosenHealing':True,'maximumRestoredTargetHP':'half-target-hit-point-maximum','excludedTypes':['undead','construct']},'Distribuisci cinque PF per livello da chierico fra creature entro trenta piedi, senza portarle oltre metà dei loro PF massimi. Non cura non morti o costrutti; un’azione con simbolo sacro e un uso di Incanalare Divinità.'),
      ('life',6,'Blessed Healer','Guaritore Benedetto',61,{'trigger':'cast-spell-of-level-one-or-higher-that-restores-HP-to-creature-other-than-self','selfHealing':'2+spellLevel'},'Quando lanci una magia dal primo livello che cura altri, recuperi tu stesso due PF più il suo livello.'),
      ('life',17,'Supreme Healing','Guarigione Suprema',61,{'trigger':'would-roll-dice-to-restore-hit-points-with-spell','eachHealingDie':'maximum-value'},'Ogni dado che tireresti per curare con un incantesimo usa il risultato massimo.'),
      ('light',1,'Bonus Cantrip','Trucchetto Aggiuntivo',62,{'learnIfMissing':'phb2014:spell:light','countsAgainstKnownCantripLimit':'not-stated-in-local-printing'},'Impari Luce se non già conosciuta; l’esclusione dal limite è esplicita nelle errata.'),
      ('light',1,'Warding Flare','Lampo di Interdizione',62,{'trigger':'visible-creature-within-30-ft-attacks-self','activation':'reaction-before-hit-or-miss','effect':'disadvantage-on-attack-roll','immuneIfAttacker':'cannot-be-blinded','resource':daily},'Una reazione prima dell’esito impone svantaggio a un attacco contro di te di una creatura visibile entro trenta piedi; chi non può essere accecato è immune. Usi pari a Saggezza, minimo uno, per riposo lungo.'),
      ('light',2,'Radiance of the Dawn','Radiosità dell’Alba',62,{'activation':'action','requires':'present-holy-symbol','resourceCost':channel,'dispelsMagicalDarknessWithinFt':30,'damageTargets':'hostile-creatures-within-30-ft','excludes':'total-cover','save':'constitution','saveDC':'cleric-spell-save-DC','damage':'2d10+clericLevel','damageType':'radiant','successfulSave':'half'},'Dissolvi l’oscurità magica entro trenta piedi e infliggi ai nemici senza copertura totale 2d10 più livello da chierico radiosi, dimezzati con TS Costituzione. Un’azione e un uso di Incanalare Divinità.'),
      ('light',6,'Improved Flare','Lampo Migliorato',62,{'wardingFlareAdditionalTrigger':'visible-creature-within-30-ft-attacks-creature-other-than-self','victimMustBeVisibleOrWithin30Ft':'not-stated'},'Puoi usare Lampo anche quando l’attaccante visibile entro trenta piedi attacca altri; il limite si applica all’attaccante.'),
      ('light',17,'Corona of Light','Corona di Luce',62,{'activation':'action','durationMinutes':1,'dismiss':'action','sunlight':True,'brightLightRadiusFt':60,'additionalDimLightFt':30,'enemyInBrightLightSaveDisadvantageAgainst':'any-spell-dealing-fire-or-radiant-damage','limitedUseResource':'not-stated'},'Un’azione crea un minuto di luce solare: sessanta piedi intensi e altri trenta fioca. I nemici nella luce intensa hanno svantaggio ai TS contro magie che infliggono fuoco o radiosi. Un’altra azione la termina; nessun numero limitato di usi è indicato.'),
      ('nature',1,'Acolyte of Nature','Accolito della Natura',63,{'chooseDruidCantrips':1,'countsAsClericCantrip':'not-stated-in-local-printing','countsAgainstKnownCantripLimit':'not-stated-in-local-printing','chooseProficientSkills':1,'skillPool':['animal-handling','nature','survival']},'Un trucchetto da druido e un’abilità fra Addestrare Animali, Natura e Sopravvivenza; classe del trucchetto e limite sono chiariti dalle errata.'),
      ('nature',1,'Bonus Proficiency','Competenza Aggiuntiva',63,{'armorProficiency':'heavy'},'Competenza nelle armature pesanti.'),
      ('nature',2,'Charm Animals and Plants','Affascinare Animali e Piante',63,{'activation':'action','requires':['present-holy-symbol','invoke-deity-name'],'resourceCost':channel,'targetTypes':['beast','plant'],'targetMust':'see-self-within-30-ft','save':'wisdom','saveDC':'cleric-spell-save-DC','failure':{'condition':'charmed-by-self','durationMinutes':1,'endsOn':'takes-damage','friendlyTo':'self-and-designated-creatures'}},'Bestie e piante che ti vedono entro trenta piedi fanno TS Saggezza o sono affascinate e amiche tue e dei designati per un minuto, fino a subire danni. Un’azione con simbolo e invocazione, un uso di Incanalare Divinità.'),
      ('nature',6,'Dampen Elements','Attenuare Elementi',63,{'trigger':'self-or-creature-within-30-ft-takes-eligible-damage','activation':'reaction','types':['acid','cold','fire','lightning','thunder'],'grantsResistance':'that-instance-of-damage','visibilityRequired':'not-stated'},'Una reazione dà resistenza a quella singola istanza di acido, freddo, fuoco, fulmine o tuono a te o una creatura entro trenta piedi.'),
      ('nature',17,'Master of Nature','Maestro della Natura',63,{'targets':'creatures-currently-charmed-by-own-Charm-Animals-and-Plants','activation':'bonus-action-on-own-turn','requires':'verbal-command','command':'what-each-creature-does-on-next-turn'},'Con azione bonus nel tuo turno comandi verbalmente la prossima azione di ogni creatura affascinata dal tuo privilegio.'),
      ('tempest',1,'Bonus Proficiencies','Competenze Aggiuntive',63,{'armorProficiency':'heavy','weaponProficiency':'martial'},'Competenza in armature pesanti e armi da guerra.'),
      ('tempest',1,'Wrath of the Storm','Collera della Tempesta',63,{'trigger':'visible-creature-within-5-ft-hits-self-with-attack','activation':'reaction','save':'dexterity','saveDC':'cleric-spell-save-DC','damage':'2d8','damageTypeChoice':['lightning','thunder'],'successfulSave':'half','resource':daily},'Reagisci a un colpo di una creatura visibile entro cinque piedi: 2d8 fulmine o tuono, dimezzati con TS Destrezza. Saggezza usi, minimo uno, per riposo lungo.'),
      ('tempest',2,'Destructive Wrath','Collera Distruttiva',63,{'trigger':'roll-lightning-or-thunder-damage','resourceCost':channel,'replaceDamageRoll':'maximum','extraActionRequired':False},'Un uso di Incanalare Divinità sostituisce un tiro di danno da fulmine o tuono con il massimo, senza un’azione aggiuntiva.'),
      ('tempest',6,'Thunderbolt Strike','Colpo del Fulmine',63,{'trigger':'deal-lightning-damage-to-Large-or-smaller-creature','mayPushFt':10,'direction':'away-from-self','saveRequired':False},'Quando infliggi fulmine a una creatura Grande o più piccola, puoi spingerla fino a dieci piedi lontano da te senza TS aggiuntivo.'),
      ('tempest',17,'Stormborn','Nato dalla Tempesta',63,{'flyingSpeed':'current-walking-speed','unavailableWhen':['underground','indoors']},'Volo pari alla velocità attuale di cammino solo all’aperto, non sottoterra.'),
      ('trickery',1,'Blessing of the Trickster','Benedizione dell’Ingannatore',64,{'activation':'action','target':'willing-touched-creature-other-than-self','advantage':'dexterity-stealth-checks','durationHours':1,'endsOn':'use-feature-again'},'Toccando un’altra creatura consenziente le dai vantaggio a Furtività per un’ora, fino a usare di nuovo il privilegio.'),
      ('trickery',2,'Invoke Duplicity','Invocare Duplicato',64,{'activation':'action','resourceCost':channel,'duplicateCount':1,'initialSpace':'visible-unoccupied-within-30-ft','durationMinutes':1,'concentration':'as-on-spell','move':{'activation':'bonus-action-on-own-turn','maximumFt':30,'destination':'visible-space-within-120-ft-of-self'},'castFromDuplicate':{'usesOwnSenses':True},'attackAdvantage':'self-and-duplicate-within-5-ft-of-creature-that-sees-illusion'},'Crei un duplicato per un minuto con concentrazione, entro trenta piedi. Un’azione bonus lo muove di trenta mantenendolo entro centoventi. Lanci dalla sua posizione usando i tuoi sensi; hai vantaggio contro chi vede l’illusione e si trova entro cinque piedi sia da te sia dal duplicato.'),
      ('trickery',6,'Cloak of Shadows','Manto di Ombre',64,{'activation':'action','resourceCost':channel,'condition':'invisible','expires':'end-of-own-next-turn','endsIf':['attack','cast-spell']},'Un’azione e un uso di Incanalare Divinità ti rendono invisibile fino al tuo prossimo fine turno, finché non attacchi o lanci una magia.'),
      ('trickery',17,'Improved Duplicity','Duplicato Migliorato',64,{'maximumDuplicates':4,'moveAnyNumber':{'activation':'bonus-action-on-own-turn','maximumFtEach':30,'maximumRangeFt':120},'sharesInvokeDuplicityConcentrationAndDuration':True},'Invocare Duplicato può creare fino a quattro illusioni; una stessa azione bonus muove qualsiasi numero di esse fino a trenta piedi ciascuna, entro centoventi da te.'),
      ('war',1,'Bonus Proficiencies','Competenze Aggiuntive',64,{'armorProficiency':'heavy','weaponProficiency':'martial'},'Competenza in armature pesanti e armi da guerra.'),
      ('war',1,'War Priest','Sacerdote di Guerra',64,{'trigger':'use-Attack-action','activation':'bonus-action','attack':'one-weapon-attack','resource':daily},'Dopo l’azione Attaccare puoi usare azione bonus per un attacco con arma. Saggezza usi, minimo uno, per riposo lungo.'),
      ('war',2,'Guided Strike','Colpo Guidato',64,{'trigger':'own-attack-roll','resourceCost':channel,'attackBonus':10,'decision':'after-seeing-roll-before-DM-declares-hit-or-miss','extraActionRequired':False},'Aggiungi dieci a un tuo attacco dopo aver visto il tiro ma prima di sapere se colpisce, spendendo Incanalare Divinità.'),
      ('war',6,"War God's Blessing",'Benedizione del Dio della Guerra',64,{'trigger':'creature-within-30-ft-makes-attack-roll','activation':'reaction','resourceCost':channel,'attackBonus':10,'decision':'after-seeing-roll-before-DM-declares-hit-or-miss','requiresSeeCreature':'not-stated'},'Una reazione e un uso di Incanalare Divinità aggiungono dieci all’attacco di una creatura entro trenta piedi, prima dell’esito.'),
      ('war',17,'Avatar of Battle','Avatar della Battaglia',64,{'damageResistances':['bludgeoning','piercing','slashing'],'condition':'nonmagical-weapons'},'Resistenza a contundente, perforante e tagliente da armi non magiche nella stampa locale; le errata ampliano agli attacchi non magici.'),
    ]
    for sub,page in [('knowledge',61),('light',62)]:
        rows.append((sub,8,'Potent Spellcasting','Incantesimi Potenti',page,{'addToDamage':'wisdomModifier','spellScope':'any-cleric-cantrip'},'Aggiungi Saggezza al danno inflitto dai trucchetti da chierico.'))
    for sub,page,damage in [('life',61,'radiant'),('nature',63,['cold','fire','lightning']),('tempest',63,'thunder'),('trickery',64,'poison'),('war',64,'same-as-weapon')]:
        rows.append((sub,8,'Divine Strike','Colpo Divino',page,{'trigger':'hit-creature-with-weapon-attack','maximumUses':'once-per-own-turn','additionalDamage':'1d8','additionalDamageFromCleric14':'2d8','damageTypeChoice':damage},'Una volta nel tuo turno aggiungi 1d8 al colpo con arma, 2d8 dal livello 14; tipo di danno del dominio, senza altri usi fuori dal tuo turno.'))
    for sub,level,name,it,pages,effect,summary in rows:
        dependencies={'Read Thoughts':['suggestion'],'Bonus Cantrip':['light']}.get(name,[])
        missing=['spellDescription:'+s for s in dependencies if not by_id['phb2014:spell:'+s]['verification']['complete']]
        e=record('subclass-feature',f'{sub}-{level}-'+slug(name),name,it,pages,{'level':level,'effect':effect},summary,missing=missing)
        e['relations']={'classId':CLASS,'subclassId':'phb2014:subclass:'+sub};added.append(e)
    for sub,(page,names) in DOMAINS.items():
        grants=[{'clericLevel':[1,3,5,7,9][i//2],'spellId':'phb2014:spell:'+slug(n),'alwaysPrepared':True,'countsAgainstPreparedLimit':False,'countsAsClericSpell':True} for i,n in enumerate(names)]
        e=record('subclass-feature',f'{sub}-1-domain-spells','Domain Spells','Incantesimi del Dominio',page,{'level':1,'effect':{'grants':grants,'spellDescriptionsVerifiedByGrantTable':False}},'Le coppie di dominio ai livelli 1, 3, 5, 7 e 9 sono sempre preparate senza occupare il limite, e sono magie da chierico per te.')
        e['sources'][0]['verification']='read-local-render';e['sources'].append(source(59,'Domain Spells'));e['fieldSources']['effect']=[0,1]
        e['relations']={'classId':CLASS,'subclassId':'phb2014:subclass:'+sub,'grantedSpellIds':[g['spellId'] for g in grants]};added.append(e)
    entities.extend(added)
    progression=[{'clericLevel':n,**{k:by_id[f'phb2014:class-level:cleric-{n}']['mechanics'][k] for k in ['spellSlots','cantripsKnown']}} for n in range(1,21)]
    turned={'durationMinutes':1,'endsOn':'takes-any-damage','movement':'as-far-away-from-self-as-possible','cannotWillinglyApproachWithinFt':30,'canTakeReactions':False,'allowedActions':['Dash','escape-movement-preventing-effect'],'ifNowhereToMoveMayUse':'Dodge'}
    core={
      'Spellcasting':(59,'Incantesimi',{'ability':'wisdom','list':'cleric','progression':progression,'spellSlotScope':'your-spells','slotRecovery':['long-rest'],'preparedLimit':'max(1,clericLevel+wisdomModifier)','preparationLevelLimit':'cleric-class-table','changePreparation':'finish-long-rest','preparationMinutes':'sum-prepared-spell-levels','ritualRequires':['cleric-spell','ritual-tag','prepared'],'focus':'holy-symbol'},'Prepari magie da chierico con Saggezza più livello di classe, minimo una, entro i livelli della propria tabella; un minuto per livello di ogni magia. Recuperi slot e cambi lista dopo riposo lungo. Il rituale richiede magia preparata; focus simbolo sacro.'),
      'Divine Domain':(59,'Dominio Divino',{'chooseSubclass':1,'subclassIds':['phb2014:subclass:'+s for s in DOMAINS],'featureLevels':[1,2,6,8,17]},'Scegli uno dei sette domini PHB al primo livello con ulteriori privilegi ai livelli 2, 6, 8 e 17.'),
      'Channel Divinity':([59,60],'Incanalare Divinità',{'maximumUsesByClericLevel':{'2':1,'6':2,'18':3},'recovery':['short-rest','long-rest'],'chooseOneEffectPerUse':True,'saveDC':'cleric-spell-save-DC'},'Gli effetti condividono un uso per riposo breve o lungo, due dal livello 6 e tre dal 18. Ogni uso sceglie un effetto; CD dei TS da chierico.'),
      'Turn Undead':(60,'Scacciare Non Morti',{'activation':'action','requires':['present-holy-symbol','speak-prayer'],'resourceCost':channel,'target':'undead-that-see-or-hear-self-within-30-ft','save':'wisdom','saveDC':'cleric-spell-save-DC','failure':turned},'Non morti entro trenta piedi che ti vedono o sentono fanno TS Saggezza. Se falliscono fuggono per un minuto o fino ai danni, senza reazioni, con azioni limitate; un uso di Incanalare Divinità.'),
      'Destroy Undead':(60,'Distruggere Non Morti',{'trigger':'undead-fails-save-against-own-Turn-Undead','instantDestructionIfCRAtMostByClericLevel':{'5':0.5,'8':1,'11':2,'14':3,'17':4}},'Il non morto che fallisce contro Scacciare viene distrutto se il GS è entro la soglia del tuo livello da chierico: metà, uno, due, tre o quattro dai livelli 5, 8, 11, 14 e 17.'),
      'Divine Intervention':(60,'Intervento Divino',{'activation':'action','requires':'describe-requested-assistance','roll':'percentile','succeedsIf':'roll<=clericLevel','automaticSuccessFromClericLevel':20,'effectChosenBy':'DM','appropriateEffect':'any-cleric-or-cleric-domain-spell','recoveryIfSuccessDays':7,'recoveryIfFailure':['long-rest']},'Descrivi l’aiuto e usa un’azione: il percentile deve essere entro il livello da chierico, successo automatico al 20. Il DM decide l’intervento. Dopo successo attendi sette giorni; dopo fallimento un riposo lungo.')
    }
    for e in entities:
        if e['kind']!='class-feature' or e['relations'].get('classId')!=CLASS:continue
        if e['name']=='Subclass Feature':
            e['mechanics']['concreteAlternativeIds']=[f['id'] for f in added if f['mechanics']['level']==e['mechanics']['level']];e['fieldSources']['concreteAlternativeIds']=[0]
        elif e['name'] in core:
            pages,it,effect,summary=core[e['name']];e.update(nameIt=it,summaryIt=summary,translation={'language':'it','status':'assistant-translation'})
            e['sources'].append(source(pages,e['name']));e['mechanics']['effect']=effect;e['fieldSources']['effect']=[len(e['sources'])-1];e['verification'].update(complete=True,missingFields=[])
    for sub in DOMAINS:
        parent=by_id['phb2014:subclass:'+sub];fs=[e for e in added if e['relations']['subclassId']==parent['id']]
        parent['relations']['featureIds']=[e['id'] for e in fs];parent['summaryIt']=' '.join(e['summaryIt'] for e in fs)
        missing=['featureEffects:'+e['id'] for e in fs if not e['verification']['complete']];parent['verification'].update(complete=not missing,missingFields=missing)
    return entities
